<script lang="ts">
  import type {Database,DatabaseViewConfig,Page,PropertyValue} from "@/features/notion-ui/variants/database/types"; import {visibleProps} from "../../lib/view-core";
  let {db,view,onRowCreate}= $props<{db:Database;view:DatabaseViewConfig;rows:Page[];onRowCreate?:(draft:{title:string;rowProps:Record<string,PropertyValue>})=>Promise<void>|void}>(); let title=$state(""),values=$state<Record<string,PropertyValue>>({}),busy=$state(false); let props=$derived(visibleProps(db,view).filter(p=>!p.type.includes("time")&&!p.type.endsWith("_by")&&!p.type.includes("formula")&&p.type!=="rollup"&&p.type!=="unique_id"));
  async function submit(){if(!onRowCreate||busy)return;busy=true;try{await onRowCreate({title:title.trim()||"Untitled",rowProps:{...values}});title="";values={};}finally{busy=false;}}
</script>
<form class="mx-auto max-w-xl space-y-4 p-5" onsubmit={(e)=>{e.preventDefault();void submit();}}><header><h4 class="text-lg font-semibold">{view.formTitle||db.name}</h4>{#if view.formDescription}<p class="text-sm text-muted-foreground">{view.formDescription}</p>{/if}</header><label class="block space-y-1"><span class="text-xs font-medium">Name</span><input class="w-full rounded-md border bg-background px-3 py-2 text-sm" bind:value={title} required/></label>{#each props as prop (prop.id)}<label class="block space-y-1"><span class="text-xs font-medium">{prop.name}</span>{#if prop.type==="checkbox"}<input type="checkbox" checked={values[prop.id]===true} onchange={(e)=>values={...values,[prop.id]:e.currentTarget.checked}}/>{:else if prop.type==="select"||prop.type==="status"}<select class="w-full rounded-md border bg-background px-3 py-2 text-sm" value={String(values[prop.id]??"")} onchange={(e)=>values={...values,[prop.id]:e.currentTarget.value||null}}><option value="">—</option>{#each prop.options??[] as o (o.id)}<option value={o.id}>{o.name}</option>{/each}</select>{:else}<input class="w-full rounded-md border bg-background px-3 py-2 text-sm" type={prop.type==="number"?"number":prop.type==="date"?"date":"text"} value={String(values[prop.id]??"")} oninput={(e)=>values={...values,[prop.id]:prop.type==="number"?Number(e.currentTarget.value):prop.type==="date"?{date:e.currentTarget.value}:e.currentTarget.value}}/>{/if}</label>{/each}<button class="rounded-md bg-foreground px-4 py-2 text-sm font-medium text-background disabled:opacity-50" disabled={!onRowCreate||busy}>{busy?"Submitting…":"Submit"}</button></form>
